    opt = gotopt = 1;
    next_token(s);
}

if (!root) {
    /* skipping */
    value = NULL;
} else {
    value = json_object_getn(root, key, key_len);
    if (!value && !opt) {
        set_error(s, "<validation>", json_error_item_not_found,
                  "Object item not found: %s", key);
        goto out;
    }
}

if (unpack(s, value, ap))
    goto out;

case 's':
    if (root && !json_is_string(root)) {
        set_error(s, "<validation>", json_error_wrong_type,
                  "Expected string, got %s%s%s", type_name(root),
                  key ? " for key " : "", key ? key : "");
        return -1;
    }

    if (!(s->flags & JSON_VALIDATE_ONLY)) {
        const char **str_target;
        size_t *len_target = NULL;

        str_target = va_arg(*ap, const char **);
        if (!str_target) {
            set_error(s, "<args>", json_error_null_value, "NULL string argument");
            return -1;
        }

        next_token(s);

        if (token(s) == '%') {
            len_target = va_arg(*ap, size_t *);
            if (!len_target) {
                set_error(s, "<args>", json_error_null_value,
                          "NULL string length argument");
                return -1;
            }
        } else
            prev_token(s);

        if (root) {
            *str_target = json_string_value(root);
            if (len_target)
                *len_target = json_string_length(root);
        }
    }
    return 0;

key = va_arg(*ap, const char *);
if (!key) {
    set_error(s, "<args>", json_error_null_value, "NULL object key");
    goto out;
}
key_len = strlen(key);

next_token(s);

if (token(s) == '?') {
    opt = gotopt = 1;
    next_token(s);
}

if (!root) {
    /* skipping */
    value = NULL;
} else {
    value = json_object_getn(root, key, key_len);
    if (!value && !opt) {
        set_error(s, "<validation>", json_error_item_not_found,
                  "Object item not found: %s", key);
        goto out;
    }
}

if (unpack(s, value, ap, key))
    goto out;

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    if (size < 2)
        return 0;

    /* Use first byte to select format variant, rest as JSON input */
    uint8_t variant = data[0] % 8;
    const char *json_str = (const char *)(data + 1);
    size_t json_len = size - 1;

    json_error_t error;
    json_t *root = json_loadb(json_str, json_len,
                               JSON_DECODE_ANY | JSON_ALLOW_NUL, &error);
    if (root == NULL)
        return 0;

/* Exercise json_unpack with simple format strings if root is an object */
if (json_is_object(root)) {
    json_t *val = NULL;
    const char *key = NULL;
    /* Unpack first key-value pair */
    void *iter = json_object_iter(root);
    if (iter != NULL) {
        key = json_object_iter_key(iter);
        val  = json_object_iter_value(iter);
        (void)key;
        (void)val;
    }

    /* json_unpack with "o" format — extract object */
    json_t *out_obj = NULL;
    json_unpack(root, "o", &out_obj);

    /* json_unpack with "{s?o}" — optional key lookup */
    json_t *field = NULL;
    json_unpack(root, "{s?o}", "data", &field);
}

/* Exercise json_unpack on array */
if (json_is_array(root) && json_array_size(root) > 0) {
    json_t *first = NULL;
    json_unpack(root, "[o!]", &first);
}
